const p = $json;
const apelidos = Array.isArray(p.aliases) && p.aliases.length > 0 ? ` - Apelidos: ${p.aliases.join(', ')}` : '';
return {
  json: {
    produto_id: p.id,
    nome: p.nome,
    preco: p.preco,
    content: `${p.nome}${apelidos} - Preço: R$ ${p.preco}`,
  },
};

const itensReais = $input.all();
let totalReal = 0;
for (const item of itensReais) {
  const v = Number(item.json.valor_total);
  if (!isNaN(v)) totalReal += v;
}
totalReal = Math.round(totalReal * 100) / 100;

const textoAgente = ($('Marca Fim Agente').first().json.output || '').toString();

let diverge = false;
let totalCitado = null;

if (/total/i.test(textoAgente) || /r\$/i.test(textoAgente)) {
  const match = textoAgente.match(/total[\s\S]{0,60}?R?\$?\s*(\d+(?:[.,]\d{1,2})?)/i);
  if (match) {
    const valorStr = match[1].replace(',', '.');
    const valor = parseFloat(valorStr);
    if (!isNaN(valor)) {
      totalCitado = valor;
      diverge = Math.abs(totalCitado - totalReal) > 0.01;
    }
  }
}

return [{ json: { diverge, totalReal, totalCitado } }];

const texto = ($('Marca Fim Agente').first().json.output || '').toString();
const padroes = [
  /não\s+temos\b/i,
  /não\s+encontr(ei|amos|ou)\b/i,
  /não\s+trabalhamos\s+com\b/i,
  /não\s+h[áa]\s+(esse|este|essa|esta)?\s*(produto|item)/i,
  /não\s+existe\s+(esse|este|essa|esta)?\s*(produto|item)/i,
  /em\s+falta\b/i,
  /indispon[íi]vel/i,
  /sem\s+estoque\b/i,
  /esgotad[oa]\b/i,
  /fora\s+de\s+estoque/i,
];
const proibido = padroes.some((p) => p.test(texto));
return [{ json: { proibido, textoOriginal: texto } }];

const candidato = ($json.text || ($json.response && $json.response.text) || '').toString().trim();
const padroes = [
  /não\s+temos\b/i,
  /não\s+encontr(ei|amos|ou)\b/i,
  /não\s+trabalhamos\s+com\b/i,
  /não\s+h[áa]\s+(esse|este|essa|esta)?\s*(produto|item)/i,
  /não\s+existe\s+(esse|este|essa|esta)?\s*(produto|item)/i,
  /em\s+falta\b/i,
  /indispon[íí]vel/i,
  /sem\s+estoque\b/i,
  /esgotad[oa]\b/i,
  /fora\s+de\s+estoque/i,
];
const aindaProibido = padroes.some((p) => p.test(candidato));
const vazio = candidato.length < 10;
const respostaFinal = (aindaProibido || vazio)
  ? 'Deixa eu confirmar isso certinho com a equipe e já te retorno, tá? 😊'
  : candidato;
return [{ json: { respostaFinal } }];
